typedef struct
{
        u64 pos;
        Double duration;
} LATMIdx;

typedef struct
{
        //filter args
        u32 frame_size;
        Double index;

        //only one input pid declared
        GF_FilterPid *ipid;
        //only one output pid declared
        GF_FilterPid *opid;

        GF_BitStream *bs;
        u64 file_pos, cts;
        u32 sr_idx, nb_ch, base_object_type;
        GF_Fraction64 duration;
